function Hero() {
    return (
        <section className="container-fluid" id="supportHero">

            {/* ROW 1 — HEADER */}
            <div className="row py-5">
                <div className="col-12 d-flex justify-content-between align-items-center px-5">
                    <h4 className="m-auto text-center flex-grow-1">Support Portal</h4>
                    <a href="#" className="text-white ms-3">Track Tickets</a>
                </div>
            </div>

            {/* ROW 2 — LEFT & RIGHT CONTENT */}
            <div className="row px-5 py-3">

                {/* LEFT COLUMN */}
                <div className="col-md-6 mb-4">
                    <h1 className="fs-4 mb-3">
                        Search for an answer or browse help topics to create a ticket
                    </h1>

                    <input
                        className="form-control mb-3 p-3"
                        placeholder="Eg. how do I activate F&O"
                    />

                    <div className="d-flex flex-wrap gap-3">
                        <a href="#">Track account opening</a>
                        <a href="#">Track segment activation</a>
                        <a href="#">Intraday margins</a>
                        <a href="#">Kite user manual</a>
                    </div>
                </div>

                {/* RIGHT COLUMN */}
                <div className="col-md-6 mb-4">
                    <h1 className="fs-4 mb-3">Featured</h1>

                    <ol className="ps-3">
                        <li><a href="#">Current Takeovers and Delisting</a></li>
                        <li><a href="#">Latest Intraday leverages – MIS & CO</a></li>
                    </ol>
                </div>

            </div>
        </section>
    );
}

export default Hero;




